/**
 * Seed script: Populates Firestore from the Excel-derived initial data.
 *
 * Usage: npx ts-node seed_firestore.ts
 *
 * Requires: firebase
 *
 * This script creates:
 * 1. A default farm + demo user
 * 2. The /nutrients master collection (measured + derived definitions)
 * 3. The real feed library parsed from docs/ALIMENTAZIONE.xlsx
 * 4. Animal groups with their nutrient target ranges
 *
 * The data comes from src/app/core/data/initial-data.ts, which is generated by
 * scripts/parse-excel.cjs. Re-run that generator to refresh the source data.
 */

import { initializeApp } from 'firebase/app';
import { getFirestore, collection, setDoc, doc } from 'firebase/firestore';
import {
  NUTRIENTS_MASTER,
  ANIMAL_GROUPS,
  FEEDS_SEED,
  TARGET_RANGES,
} from './src/app/core/data/initial-data';

// Firebase config from environment.ts
const firebaseConfig = {
  apiKey: 'AIzaSyDd2YE25IMP3eLTghPljr_5v9O9Y2Z2mnQ',
  authDomain: 'nicola-milk-farm.firebaseapp.com',
  projectId: 'nicola-milk-farm',
  storageBucket: 'nicola-milk-farm.firebasestorage.app',
  messagingSenderId: '475192543430',
  appId: '1:475192543430:web:fbe259dcc04ae98eb3afc7',
};

const app = initializeApp(firebaseConfig, 'seed-app');
const db = getFirestore(app);

async function seed(): Promise<void> {
  console.log('🌱 Seeding Firestore from Excel-derived data...\n');

  // ── Nutrient master collection ──
  const nutrientsRef = collection(db, 'nutrients');
  for (const n of NUTRIENTS_MASTER) {
    await setDoc(doc(nutrientsRef, n.code), n);
  }
  console.log(`✅ Nutrients master: ${NUTRIENTS_MASTER.length} definitions`);

  // ── Farm + demo user ──
  const farmId = 'seed-farm-' + Date.now();
  const uid = 'seed-user-' + Date.now();

  await setDoc(doc(db, 'farms', farmId), {
    id: farmId,
    name: 'Demo Farm (Seed Data)',
    ownerUid: uid,
    createdAt: new Date(),
  });
  console.log(`✅ Created farm: ${farmId}`);

  await setDoc(doc(db, 'users', uid), {
    uid,
    displayName: 'Demo User',
    email: 'demo@milkfarm.local',
    farmId,
    language: 'it' as const,
    createdAt: new Date(),
  });
  console.log(`✅ Created user: ${uid}`);

  // ── Feeds ──
  const feedsRef = collection(db, 'feeds');
  for (const feed of FEEDS_SEED) {
    const feedDoc = doc(feedsRef);
    await setDoc(feedDoc, {
      ...feed,
      farmId,
      updatedAt: new Date(),
    });
  }
  console.log(`✅ Created ${FEEDS_SEED.length} feeds`);

  // ── Animal groups + targets ──
  const groupsRef = collection(db, 'animalGroups');
  for (const group of ANIMAL_GROUPS) {
    await setDoc(doc(groupsRef, group.id), group);

    const targets = TARGET_RANGES[group.id] ?? [];
    const targetsRef = collection(db, 'animalGroups', group.id, 'targets');
    for (const target of targets) {
      await setDoc(doc(targetsRef, target.nutrientCode), target);
    }
    console.log(
      `  ✅ Animal group: ${group.nameIt} (${group.id}) — ${targets.length} targets`,
    );
  }

  console.log('\n✅ Seed complete!');
  console.log(`   Farm: ${farmId}`);
  console.log(`   User: ${uid}`);
  console.log(
    '\nNote: create a Firebase Auth user (via the console) to log in against this farm.\n',
  );
}

seed().catch((err) => {
  console.error('❌ Seed failed:', err);
  process.exit(1);
});
